"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6441],{38351:e=>{e.exports=JSON.parse('{"functions":[{"name":"CreateFullViewport","desc":"Creates the rig and returns its three pieces.\\n\\nThe [ScreenGui] is created disabled and **unparented** \u2014 parent it to the player\'s\\nPlayerGui and set `Enabled = true` when you want it shown. The viewport is\\nnon-interactable, so it never swallows input from the UI beneath it.\\n\\nNothing is cleaned up automatically; destroy the returned ScreenGui when done and\\nthe camera and viewport go with it.\\n\\n```lua\\nlocal screenGui, camera, viewport = CreateFullViewport()\\n\\nmodel.Parent = viewport\\ncamera.CFrame = CFrame.lookAt(cameraPosition, model:GetPivot().Position)\\n\\nscreenGui.Parent = playerGui\\nscreenGui.Enabled = true\\n```","params":[],"returns":[{"desc":"","lua_type":"(ScreenGui, Camera, ViewportFrame)"}],"function_type":"static","realm":["Client"],"source":{"line":41,"path":"src/Shared/Class/CreateFullViewport.luau"}}],"properties":[],"types":[],"name":"CreateFullViewport","desc":"Builds a fullscreen [ViewportFrame] rig for rendering 3D content over the whole\\nscreen \u2014 highlight prompts, item showcases, cutscene overlays.\\n\\nEvery inset and safe-area behaviour is switched off so the viewport really does\\ncover the display edge to edge, and its `DisplayOrder` is negative so it sits\\nbehind normal UI rather than on top of it.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":14,"path":"src/Shared/Class/CreateFullViewport.luau"}}')}}]);